fn balanced(text:&str)->bool {
    let mut stack=Vec::new();
    for c in text.chars() {
        match c {
            '('|'['|'{' => stack.push(c),
            ')'|']'|'}' => {
                let expected=match c { ')'=>'(', ']'=>'[', _=>'{' };
                if stack.pop()!=Some(expected) { return false; }
            }
            _=>{}
        }
    }
    stack.is_empty()
}

fn main() {
    let result = balanced("([)]").to_string();
    println!("{result}");
}

